script:
frappe.ui.form.on("Coupon Juksu", {
    salutation: function(frm) {
        update_fullname(frm);
    },
    namef: function(frm) {
        update_fullname(frm);
    },
    lastname: function(frm) {
        update_fullname(frm);
    }
});

function update_fullname(frm) {
    const salutation = frm.doc.salutation || "";
    const namef = frm.doc.namef || "";
    const lastname = frm.doc.lastname || "";
    const fullname = `${salutation}${namef} ${lastname}`.trim();

    frm.set_value("fullname", fullname);
}


// ✅ Event: เมื่อเพิ่มแถวเอง (optional ถ้ายังให้ user เพิ่มเองได้)
frappe.ui.form.on('Coupon Juksu Table', {
    coupon_juksu_table_add: function(frm, cdt, cdn) {
        frappe.call({
            method: 'erpnext.coupon_juksu.generate_unique_coupon_code',
            callback: function(r) {
                if (r.message) {
                    frappe.model.set_value(cdt, cdn, 'coupon_code', r.message);
                    frappe.model.set_value(cdt, cdn, 'barcode_coupon', r.message);
                    frm.refresh_field('coupon_juksu_table');
                } else {
                    frappe.msgprint("เกิดข้อผิดพลาดในการ gen โค้ด");
                }
            }
        });
    },

    // ✅ เมื่อแก้ไข coupon_code ด้วยตัวเอง
    coupon_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.coupon_code) {
            frappe.model.set_value(cdt, cdn, "barcode_coupon", row.coupon_code);
        }
    }
});


// ✅ Event: ปุ่มกดดึงข้อมูลทั้งหมด
frappe.ui.form.on('Coupon Juksu', {
    retrieve_information: function(frm) {
        const receipt_no = frm.doc.receipt_no;

        if (!receipt_no) {
            frappe.msgprint("กรุณาระบุเลขที่ใบเสร็จ");
            return;
        }

        frm.clear_table("coupon_juksu_table");
        frm.refresh_field("coupon_juksu_table");

        frm.set_df_property("display", "hidden", false);
        frm.fields_dict["display"].$wrapper.html(`
            <div id="spinner-r" style="color: #555; font-size: 14px;">
                <i class="fa fa-spinner fa-spin" style="margin-right: 5px;"></i>
                กำลังดึงข้อมูล ...
            </div>
        `);

        frappe.call({
            method: "erpnext.hospital_receipt_credit_coupon.get_hospital_receipt_coupon",
            args: {
                receipt_no: receipt_no
            },
            callback: function(r) {
                $('#spinner-r').remove();

                if (r.message && r.message.length > 0) {
                    let totalRows = r.message.length;
                    let processed = 0;

                    r.message.forEach(function(row, index) {
                        let new_row = frm.add_child("coupon_juksu_table");

                        let clean_packet_name = row.billing_name
                            .split('\n')
                            .filter(line => !line.trim().startsWith('-'))
                            .join(' ')
                            .trim();

                        frappe.model.set_value(new_row.doctype, new_row.name, 'packet_name', clean_packet_name);

                        // ✅ Generate coupon code สำหรับแต่ละแถว
                        frappe.call({
                            method: 'erpnext.coupon_juksu.generate_unique_coupon_code',
                            callback: function(res) {
                                if (res.message) {
                                    frappe.model.set_value(new_row.doctype, new_row.name, 'coupon_code', res.message);
                                    frappe.model.set_value(new_row.doctype, new_row.name, 'barcode_coupon', res.message);
                                } else {
                                    frappe.msgprint(`เกิดข้อผิดพลาดในการ gen โค้ดแถวที่ ${index + 1}`);
                                }

                                processed++;

                                // ✅ เมื่อประมวลผลครบทุกแถว
                                if (processed === totalRows) {
                                    frm.refresh_field("coupon_juksu_table");

                                    // ✅ เปลี่ยนสถานะเอกสาร
                                    frm.set_value("wf_coupon_state", "ออกเลขคูปองแล้ว");

                                    // ✅ Save อัตโนมัติ และสร้างเอกสาร Coupon Detail Juksu หลังบันทึก
                                    frm.save().then(() => {
                                        frappe.call({
                                            method: "erpnext.create_coupon.create_coupon_detail_juksu_docs",
                                            args: {
                                                coupon_juksu_name: frm.doc.name
                                            },
                                            callback: function(r) {
                                                if (r.message.status === "success") {
                                                    frappe.msgprint(__("สร้าง Coupon Detail Juksu สำเร็จ: " + r.message.created.join(", ")));
                                                    frm.reload_doc();
                                                } else {
                                                    frappe.msgprint(__("ผิดพลาด: " + r.message.message));
                                                }
                                            }
                                        });
                                    });

                                    frm.fields_dict["display"].$wrapper.append(`
                                        <div id="result-r" style="color: green;">
                                            <i class="fa fa-check-circle"></i> ดึงข้อมูลสำเร็จ และบันทึกอัตโนมัติ
                                        </div>
                                    `);
                                }
                            }
                        });
                    });

                } else {
                    frm.fields_dict["display"].$wrapper.append(`
                        <div style="color: orange;">
                            <i class="fa fa-exclamation-circle"></i> ไม่พบข้อมูลใบเสร็จ
                        </div>
                    `);
                }
            }
        });
    }
});

frappe.ui.form.on('Search Coupon', {
    validate: function(frm) {
        let new_state;
        if (['ใช้แล้ว'].includes(frm.doc.wf_search_coupon_state)) {
            new_state = 'ใช้แล้ว';
        }

        if (new_state && frm.doc.coupon_detail_juksu) {
            frappe.call({
                method: 'frappe.client.set_value',
                args: {
                    doctype: 'Coupon Detail Juksu',
                    name: frm.doc.coupon_detail_juksu,
                    fieldname: 'wf_coupon_detail_state',
                    value: new_state
                },
                callback: function(response) {
                    if (!response.exc) {
                        console.log(`✅ Successfully updated`);
                    } else {
                        console.error(`❌ Failed to update`, response.exc);
                    }
                }
            });
        } else {
            console.log("🚫 No update: state not matched or coupon_detail_juksu is missing");
        }
    }
});
